import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const ACCOUNT_TYPES = ['ASSET', 'LIABILITY', 'EQUITY', 'REVENUE_EXPENSE'];
const GROUP_TYPES = ['FUND', 'MAIN', 'RECEIVABLE_PAYABLE', 'USER_DEFINED'];
const USE_STATUSES = ['사용', '미사용'];

function text(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function optText(v: unknown): string | null {
  return typeof v === 'string' ? v : null;
}

function paging(q: Record<string, unknown>): { page: number; size: number } {
  const rawPage = Number(q['page'] ?? 0);
  const rawSize = Number(q['size'] ?? 20);
  const page = Number.isInteger(rawPage) && rawPage >= 0 ? rawPage : 0;
  const size = Number.isInteger(rawSize) && rawSize > 0 ? Math.min(rawSize, 200) : 20;
  return { page, size };
}

function optId(v: unknown): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  const n = Number(v);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 ID 형식이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr00601Controller {
  @Post('/account-items')
  @HttpCode(200)
  async createAccountItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const accountType = text(data['accountType']);
    const accountCode = text(data['accountCode']);
    const accountName = text(data['accountName']);
    if (!accountType || !accountCode || !accountName) {
      throw new ApiError(422, 'ACCOUNT_REQUIRED_MISSING', '계정 유형, 코드, 명칭은 필수 항목입니다.');
    }
    if (!ACCOUNT_TYPES.includes(accountType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정 유형이 올바르지 않습니다.');
    }
    if (accountCode.length > 20 || accountName.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 코드 또는 명칭이 너무 깁니다.');
    }
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_code = :accountCode',
        { accountCode },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ACCOUNT_CODE_DUPLICATED', '이미 존재하는 계정과목 코드입니다.');
      }
      const rows = await db.query(
        `INSERT INTO account_item (account_type, account_code, account_name, description, remark, created_at, updated_at)
         VALUES (:accountType, :accountCode, :accountName, :description, :remark, now(), now())
         RETURNING account_item_id AS "accountItemId", account_type AS "accountType",
                   account_code AS "accountCode", account_name AS "accountName"`,
        {
          accountType,
          accountCode,
          accountName,
          description: optText(data['description']),
          remark: optText(data['remark']),
        },
      );
      return rows[0];
    });
  }

  @Patch('/account-items/:accountItemId')
  async updateAccountItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const idText = req.params['accountItemId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '계정과목이 존재하지 않습니다.');
    }
    const accountType = optText(data['accountType']);
    if (accountType !== null && !ACCOUNT_TYPES.includes(accountType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정 유형이 올바르지 않습니다.');
    }
    const accountName = optText(data['accountName']);
    if (accountName !== null && (accountName.trim() === '' || accountName.length > 100)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 명칭이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `UPDATE account_item
            SET account_type = COALESCE(CAST(:accountType AS varchar), account_type),
                account_name = COALESCE(CAST(:accountName AS varchar), account_name),
                description = COALESCE(CAST(:description AS text), description),
                remark = COALESCE(CAST(:remark AS text), remark),
                updated_at = now()
          WHERE account_item_id = CAST(:id AS bigint)
          RETURNING account_item_id AS "accountItemId"`,
        {
          id: idText,
          accountType,
          accountName,
          description: optText(data['description']),
          remark: optText(data['remark']),
        },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '계정과목이 존재하지 않습니다.');
      }
      return rows[0];
    });
  }

  @Get('/account-items')
  async listAccountItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = paging(q);
    const accountType = text(q['accountType']) || null;
    if (accountType !== null && !ACCOUNT_TYPES.includes(accountType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정 유형이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT account_item_id AS "accountItemId", account_type AS "accountType",
                account_code AS "accountCode", account_name AS "accountName",
                description AS "description", remark AS "remark"
           FROM account_item
          WHERE (CAST(:accountType AS varchar) IS NULL OR account_type = CAST(:accountType AS varchar))
          ORDER BY account_code
          LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { accountType, size, offset: page * size },
      );
      const cnt = await db.query(
        `SELECT COUNT(*) AS "total" FROM account_item
          WHERE (CAST(:accountType AS varchar) IS NULL OR account_type = CAST(:accountType AS varchar))`,
        { accountType },
      );
      return { items, page, size, total: Number(cnt[0].total) };
    });
  }

  @Post('/account-groups')
  @HttpCode(200)
  async createAccountGroup(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const groupType = text(data['groupType']);
    const groupName = text(data['groupName']);
    if (!groupType || !groupName) {
      throw new ApiError(422, 'ACCOUNT_GROUP_REQUIRED_MISSING', '관련계정 유형과 그룹명은 필수 항목입니다.');
    }
    if (!GROUP_TYPES.includes(groupType) || groupName.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '관련계정 유형 또는 그룹명이 올바르지 않습니다.');
    }
    const rawIds = data['accountItemIds'];
    if (!Array.isArray(rawIds) || rawIds.length === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '그룹에 포함할 계정과목을 하나 이상 선택해 주세요.');
    }
    const ids: number[] = [];
    for (const raw of rawIds) {
      const n = Number(raw);
      if (raw === null || raw === '' || !Number.isInteger(n)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 ID 형식이 올바르지 않습니다.');
      }
      if (!ids.includes(n)) {
        ids.push(n);
      }
    }
    return transaction(async (db) => {
      for (const id of ids) {
        const found = await db.query(
          'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:id AS bigint)',
          { id },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '구성 계정과목이 존재하지 않습니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO account_group (group_type, group_name, created_at, updated_at)
         VALUES (:groupType, :groupName, now(), now())
         RETURNING account_group_id AS "accountGroupId"`,
        { groupType, groupName },
      );
      const groupId = rows[0].accountGroupId;
      for (const id of ids) {
        await db.execute(
          `INSERT INTO account_group_item (account_group_id, account_item_id, created_at, updated_at)
           VALUES (CAST(:groupId AS bigint), CAST(:id AS bigint), now(), now())`,
          { groupId, id },
        );
      }
      return rows[0];
    });
  }

  @Get('/account-groups')
  async listAccountGroups(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = paging(q);
    const groupType = text(q['groupType']) || null;
    if (groupType !== null && !GROUP_TYPES.includes(groupType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '관련계정 유형이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT account_group_id AS "accountGroupId", group_type AS "groupType", group_name AS "groupName"
           FROM account_group
          WHERE (CAST(:groupType AS varchar) IS NULL OR group_type = CAST(:groupType AS varchar))
          ORDER BY account_group_id DESC
          LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { groupType, size, offset: page * size },
      );
      const cnt = await db.query(
        `SELECT COUNT(*) AS "total" FROM account_group
          WHERE (CAST(:groupType AS varchar) IS NULL OR group_type = CAST(:groupType AS varchar))`,
        { groupType },
      );
      return { items, page, size, total: Number(cnt[0].total) };
    });
  }

  @Post('/management-items')
  @HttpCode(200)
  async createManagementItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const rawAccount = data['accountItemId'];
    const accountItemId = Number(rawAccount);
    const itemName = text(data['itemName']);
    const useStatus = text(data['useStatus']);
    if (rawAccount === undefined || rawAccount === null || rawAccount === '' || !Number.isInteger(accountItemId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정과목을 선택해 주세요.');
    }
    if (!itemName || itemName.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '관리항목명을 입력해 주세요.');
    }
    if (!USE_STATUSES.includes(useStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부는 사용 또는 미사용이어야 합니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '계정과목이 존재하지 않습니다.');
      }
      const dup = await db.query(
        `SELECT management_item_id FROM management_item
          WHERE account_item_id = CAST(:accountItemId AS bigint) AND item_name = :itemName`,
        { accountItemId, itemName },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'MANAGEMENT_ITEM_DUPLICATED', '이미 같은 이름의 관리항목이 있습니다.');
      }
      // 가정: 이 API로 추가하는 관리항목은 사용자 정의 항목(true)이다.
      const rows = await db.query(
        `INSERT INTO management_item (account_item_id, item_name, is_user_defined, use_status, remark, created_at, updated_at)
         VALUES (CAST(:accountItemId AS bigint), :itemName, true, :useStatus, :remark, now(), now())
         RETURNING management_item_id AS "managementItemId"`,
        { accountItemId, itemName, useStatus, remark: optText(data['remark']) },
      );
      return rows[0];
    });
  }

  @Patch('/management-items/:managementItemId')
  async updateManagementItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const idText = req.params['managementItemId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(404, 'MANAGEMENT_ITEM_NOT_FOUND', '관리항목이 존재하지 않습니다.');
    }
    const useStatus = optText(data['useStatus']);
    if (useStatus !== null && !USE_STATUSES.includes(useStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부는 사용 또는 미사용이어야 합니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `UPDATE management_item
            SET use_status = COALESCE(CAST(:useStatus AS varchar), use_status),
                remark = COALESCE(CAST(:remark AS text), remark),
                updated_at = now()
          WHERE management_item_id = CAST(:id AS bigint)
          RETURNING management_item_id AS "managementItemId"`,
        { id: idText, useStatus, remark: optText(data['remark']) },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MANAGEMENT_ITEM_NOT_FOUND', '관리항목이 존재하지 않습니다.');
      }
      return rows[0];
    });
  }

  @Get('/management-items')
  async listManagementItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = paging(q);
    const accountItemId = optId(q['accountItemId']);
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT management_item_id AS "managementItemId", account_item_id AS "accountItemId",
                item_name AS "itemName", is_user_defined AS "isUserDefined",
                use_status AS "useStatus", remark AS "remark"
           FROM management_item
          WHERE (CAST(:accountItemId AS bigint) IS NULL OR account_item_id = CAST(:accountItemId AS bigint))
          ORDER BY management_item_id DESC
          LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { accountItemId, size, offset: page * size },
      );
      const cnt = await db.query(
        `SELECT COUNT(*) AS "total" FROM management_item
          WHERE (CAST(:accountItemId AS bigint) IS NULL OR account_item_id = CAST(:accountItemId AS bigint))`,
        { accountItemId },
      );
      return { items, page, size, total: Number(cnt[0].total) };
    });
  }
}

