import { useState } from 'react';
import { call, useData, Badge, Tiles, Filters, Band, DataTable, Pager, Drawer, Form, Field, TextInput, Select, LookupSelect, RefName, ErrorText } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const ACCOUNT_TYPES: [string, string][] = [
  ['ASSET', '자산'],
  ['LIABILITY', '부채'],
  ['EQUITY', '자본'],
  ['REVENUE_EXPENSE', '수익·비용'],
];
const GROUP_TYPES: [string, string][] = [
  ['FUND', '자금계정'],
  ['MAIN', '주요계정'],
  ['RECEIVABLE_PAYABLE', '채권·채무계정'],
  ['USER_DEFINED', '사용자 정의'],
];
const USE_STATUSES: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

function typeName(options: [string, string][], v: unknown): string {
  const found = options.find((o) => o[0] === v);
  return found ? found[1] : String(v ?? '');
}

interface Open {
  kind: 'accountCreate' | 'accountEdit' | 'groupCreate' | 'mgmtCreate' | 'mgmtEdit';
  row?: Row;
}

export default function FnSfr00601Page({ role, notify }: PageProps) {
  const [acctDraft, setAcctDraft] = useState('');
  const [acctType, setAcctType] = useState('');
  const [acctPage, setAcctPage] = useState(0);
  const [groupDraft, setGroupDraft] = useState('');
  const [groupType, setGroupType] = useState('');
  const [groupPage, setGroupPage] = useState(0);
  const [mgmtDraft, setMgmtDraft] = useState<number | string>('');
  const [mgmtAccount, setMgmtAccount] = useState<number | string>('');
  const [mgmtPage, setMgmtPage] = useState(0);
  const [open, setOpen] = useState<Open | null>(null);
  const [f, setF] = useState<Row>({});
  const [groupIds, setGroupIds] = useState<(number | string)[]>([]);
  const [pick, setPick] = useState<number | string>('');

  const accounts = useData<Page>(
    () => call<Page>('GET', '/account-items', role, undefined, { accountType: acctType, page: acctPage, size: 20 }),
    [acctType, acctPage],
  );
  const groups = useData<Page>(
    () => call<Page>('GET', '/account-groups', role, undefined, { groupType, page: groupPage, size: 20 }),
    [groupType, groupPage],
  );
  const mgmts = useData<Page>(
    () => call<Page>('GET', '/management-items', role, undefined, { accountItemId: mgmtAccount, page: mgmtPage, size: 20 }),
    [mgmtAccount, mgmtPage],
  );

  const set = (key: string, v: unknown) => setF({ ...f, [key]: v });

  const reloadAll = () => {
    accounts.reload();
    groups.reload();
    mgmts.reload();
  };

  const start = (kind: Open['kind'], row?: Row) => {
    setPick('');
    setGroupIds([]);
    if (kind === 'accountEdit' && row) {
      setF({
        accountType: row.accountType,
        accountName: row.accountName,
        description: row.description ?? '',
        remark: row.remark ?? '',
      });
    } else if (kind === 'mgmtEdit' && row) {
      setF({ useStatus: row.useStatus, remark: row.remark ?? '' });
    } else if (kind === 'mgmtCreate') {
      setF({ useStatus: '사용' });
    } else {
      setF({});
    }
    setOpen({ kind, row });
  };

  const done = (text: string) => {
    setOpen(null);
    notify(text);
    reloadAll();
  };

  const createAccount = async () => {
    if (!f.accountType || !String(f.accountCode ?? '').trim() || !String(f.accountName ?? '').trim()) {
      throw new Error('계정 유형, 계정과목 코드, 계정과목 명칭을 모두 입력해 주세요.');
    }
    await call('POST', '/account-items', role, {
      accountType: f.accountType,
      accountCode: f.accountCode,
      accountName: f.accountName,
      description: f.description,
      remark: f.remark,
    });
    done('계정과목을 등록했습니다.');
  };

  const editAccount = async () => {
    if (!open || !open.row) {
      return;
    }
    if (!String(f.accountName ?? '').trim()) {
      throw new Error('계정과목 명칭을 입력해 주세요.');
    }
    await call('PATCH', '/account-items/' + String(open.row.accountItemId), role, {
      accountType: f.accountType,
      accountName: f.accountName,
      description: f.description,
      remark: f.remark,
    });
    done('계정과목을 수정했습니다.');
  };

  const createGroup = async () => {
    if (!f.groupType || !String(f.groupName ?? '').trim()) {
      throw new Error('관련계정 유형과 그룹명을 입력해 주세요.');
    }
    if (groupIds.length === 0) {
      throw new Error('그룹에 포함할 계정과목을 하나 이상 추가해 주세요.');
    }
    await call('POST', '/account-groups', role, {
      groupType: f.groupType,
      groupName: f.groupName,
      accountItemIds: groupIds,
    });
    done('관련계정 그룹을 등록했습니다.');
  };

  const createMgmt = async () => {
    if (f.accountItemId === undefined || f.accountItemId === '' || !String(f.itemName ?? '').trim() || !f.useStatus) {
      throw new Error('계정과목, 관리항목명, 사용 여부를 입력해 주세요.');
    }
    await call('POST', '/management-items', role, {
      accountItemId: f.accountItemId,
      itemName: f.itemName,
      useStatus: f.useStatus,
      remark: f.remark,
    });
    done('관리항목을 추가했습니다.');
  };

  const editMgmt = async () => {
    if (!open || !open.row) {
      return;
    }
    await call('PATCH', '/management-items/' + String(open.row.managementItemId), role, {
      useStatus: f.useStatus,
      remark: f.remark,
    });
    done('관리항목을 수정했습니다.');
  };

  const addGroupItem = () => {
    if (pick === '' || groupIds.includes(pick)) {
      return;
    }
    setGroupIds([...groupIds, pick]);
    setPick('');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>등록 현황</h2>
        <Tiles
          items={[
            ['계정과목', accounts.data ? accounts.data.total : '-'],
            ['관련계정 그룹', groups.data ? groups.data.total : '-'],
            ['관리항목', mgmts.data ? mgmts.data.total : '-'],
          ]}
        />
      </section>

      <section className="box span-12">
        <h2>계정과목</h2>
        <Filters
          onSearch={() => {
            setAcctPage(0);
            setAcctType(acctDraft);
          }}
          onReset={() => {
            setAcctDraft('');
            setAcctPage(0);
            setAcctType('');
          }}
        >
          <Field label="계정 유형">
            <Select value={acctDraft} onChange={setAcctDraft} options={ACCOUNT_TYPES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={accounts.data ? accounts.data.total : 0}>
          <button onClick={() => start('accountCreate')}>계정과목 등록</button>
        </Band>
        {accounts.error ? <ErrorText text={accounts.error} /> : null}
        <DataTable
          rows={accounts.data ? accounts.data.items : []}
          empty="등록된 계정과목이 없습니다."
          columns={[
            { key: 'accountType', label: '계정 유형', render: (r) => <Badge value={typeName(ACCOUNT_TYPES, r.accountType)} /> },
            { key: 'accountCode', label: '계정과목 코드' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'description', label: '계정 설명' },
            { key: 'remark', label: '계정 비고' },
            { key: 'edit', label: '처리', render: (r) => <button onClick={() => start('accountEdit', r)}>수정</button> },
          ]}
        />
        <Pager page={acctPage} size={20} total={accounts.data ? accounts.data.total : 0} onPage={setAcctPage} />
      </section>

      <section className="box span-6">
        <h2>관련계정 그룹</h2>
        <Filters
          onSearch={() => {
            setGroupPage(0);
            setGroupType(groupDraft);
          }}
          onReset={() => {
            setGroupDraft('');
            setGroupPage(0);
            setGroupType('');
          }}
        >
          <Field label="관련계정 유형">
            <Select value={groupDraft} onChange={setGroupDraft} options={GROUP_TYPES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={groups.data ? groups.data.total : 0}>
          <button onClick={() => start('groupCreate')}>그룹 등록</button>
        </Band>
        {groups.error ? <ErrorText text={groups.error} /> : null}
        <DataTable
          rows={groups.data ? groups.data.items : []}
          empty="등록된 그룹이 없습니다."
          columns={[
            { key: 'groupType', label: '관련계정 유형', render: (r) => <Badge value={typeName(GROUP_TYPES, r.groupType)} /> },
            { key: 'groupName', label: '그룹명' },
          ]}
        />
        <Pager page={groupPage} size={20} total={groups.data ? groups.data.total : 0} onPage={setGroupPage} />
      </section>

      <section className="box span-6">
        <h2>관리항목</h2>
        <Filters
          onSearch={() => {
            setMgmtPage(0);
            setMgmtAccount(mgmtDraft);
          }}
          onReset={() => {
            setMgmtDraft('');
            setMgmtPage(0);
            setMgmtAccount('');
          }}
        >
          <Field label="계정과목">
            <LookupSelect table="account_item" role={role} value={mgmtDraft} onChange={setMgmtDraft} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={mgmts.data ? mgmts.data.total : 0}>
          <button onClick={() => start('mgmtCreate')}>관리항목 추가</button>
        </Band>
        {mgmts.error ? <ErrorText text={mgmts.error} /> : null}
        <DataTable
          rows={mgmts.data ? mgmts.data.items : []}
          empty="등록된 관리항목이 없습니다."
          columns={[
            { key: 'accountItemId', label: '계정과목', render: (r) => <RefName table="account_item" role={role} value={r.accountItemId} /> },
            { key: 'itemName', label: '관리항목명' },
            { key: 'isUserDefined', label: '사용자 정의 여부', render: (r) => (r.isUserDefined ? '예' : '아니오') },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r.useStatus} /> },
            { key: 'remark', label: '비고' },
            { key: 'edit', label: '처리', render: (r) => <button onClick={() => start('mgmtEdit', r)}>수정</button> },
          ]}
        />
        <Pager page={mgmtPage} size={20} total={mgmts.data ? mgmts.data.total : 0} onPage={setMgmtPage} />
      </section>

      {open && open.kind === 'accountCreate' ? (
        <Drawer title="계정과목 등록" onClose={() => setOpen(null)}>
          <Form onSubmit={createAccount} submit="등록">
            <Field label="계정 유형" required>
              <Select value={f.accountType} onChange={(v) => set('accountType', v)} options={ACCOUNT_TYPES} />
            </Field>
            <Field label="계정과목 코드" required>
              <TextInput value={f.accountCode} onChange={(v) => set('accountCode', v)} />
            </Field>
            <Field label="계정과목 명칭" required>
              <TextInput value={f.accountName} onChange={(v) => set('accountName', v)} />
            </Field>
            <Field label="계정 설명" wide>
              <TextInput multiline value={f.description} onChange={(v) => set('description', v)} />
            </Field>
            <Field label="계정 비고" wide>
              <TextInput multiline value={f.remark} onChange={(v) => set('remark', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {open && open.kind === 'accountEdit' && open.row ? (
        <Drawer title="계정과목 수정" onClose={() => setOpen(null)}>
          <Form onSubmit={editAccount} submit="수정">
            <Field label="계정과목 코드">
              <TextInput value={open.row.accountCode} onChange={() => undefined} />
            </Field>
            <Field label="계정 유형">
              <Select value={f.accountType} onChange={(v) => set('accountType', v)} options={ACCOUNT_TYPES} />
            </Field>
            <Field label="계정과목 명칭" required>
              <TextInput value={f.accountName} onChange={(v) => set('accountName', v)} />
            </Field>
            <Field label="계정 설명" wide>
              <TextInput multiline value={f.description} onChange={(v) => set('description', v)} />
            </Field>
            <Field label="계정 비고" wide>
              <TextInput multiline value={f.remark} onChange={(v) => set('remark', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {open && open.kind === 'groupCreate' ? (
        <Drawer title="관련계정 그룹 등록" onClose={() => setOpen(null)}>
          <Form onSubmit={createGroup} submit="등록">
            <Field label="관련계정 유형" required>
              <Select value={f.groupType} onChange={(v) => set('groupType', v)} options={GROUP_TYPES} />
            </Field>
            <Field label="그룹명" required>
              <TextInput value={f.groupName} onChange={(v) => set('groupName', v)} />
            </Field>
            <Field label="그룹에 포함할 계정과목" required wide>
              <LookupSelect table="account_item" role={role} value={pick} onChange={setPick} />
              <button type="button" onClick={addGroupItem}>추가</button>
              <ul>
                {groupIds.map((id) => (
                  <li key={String(id)}>
                    <RefName table="account_item" role={role} value={id} />
                    <button type="button" onClick={() => setGroupIds(groupIds.filter((x) => x !== id))}>삭제</button>
                  </li>
                ))}
              </ul>
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {open && open.kind === 'mgmtCreate' ? (
        <Drawer title="사용자 정의 관리항목 추가" onClose={() => setOpen(null)}>
          <Form onSubmit={createMgmt} submit="추가">
            <Field label="계정과목" required>
              <LookupSelect table="account_item" role={role} value={f.accountItemId} onChange={(v) => set('accountItemId', v)} />
            </Field>
            <Field label="관리항목명" required>
              <TextInput value={f.itemName} onChange={(v) => set('itemName', v)} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={f.useStatus} onChange={(v) => set('useStatus', v)} options={USE_STATUSES} />
            </Field>
            <Field label="비고" wide>
              <TextInput multiline value={f.remark} onChange={(v) => set('remark', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {open && open.kind === 'mgmtEdit' && open.row ? (
        <Drawer title="관리항목 수정" onClose={() => setOpen(null)}>
          <Form onSubmit={editMgmt} submit="수정">
            <Field label="관리항목명">
              <TextInput value={open.row.itemName} onChange={() => undefined} />
            </Field>
            <Field label="사용 여부">
              <Select value={f.useStatus} onChange={(v) => set('useStatus', v)} options={USE_STATUSES} />
            </Field>
            <Field label="비고" wide>
              <TextInput multiline value={f.remark} onChange={(v) => set('remark', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
